    @media (max-width: 640px) {
      .app { padding: 12px; }
      .hero { flex-direction: column; }
      .metrics { grid-template-columns: 1fr; }
      .panel { border-radius: 18px; padding: 12px; }
      textarea { min-height: 360px; font-size: 15px; }
      button { width: 100%; }
